import {SPECIES,ELEMENTS,ITEMS} from './data.js';
import {BOND_CHRONICLES,BOND_REQUIREMENTS} from './bond-stories.js';
import {bondStatus,bondChapter,bondReward} from './bond-engine.js';
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const portrait=(species,size=96)=>`<canvas width="${size*2}" height="${size*2}" style="width:${size}px;height:${size}px" data-species="${species}" aria-hidden="true"></canvas>`;
const rewardMarkup=reward=>Object.entries(reward).map(([id,n])=>`<span><canvas width="32" height="32" data-item="${id}" aria-hidden="true"></canvas>${ITEMS[id].name} × ${n}</span>`).join('');

export function bondIndexMarkup(game,filter='owned'){
 const statuses=Object.keys(BOND_CHRONICLES).map(f=>bondStatus(game,f));
 const ready=statuses.filter(s=>s.ready).length,read=statuses.reduce((n,s)=>n+s.step,0);
 const shown=statuses.filter(s=>filter==='all'||filter==='ready'?filter==='all'||s.ready:!!s.mon).sort((a,b)=>Number(b.ready)-Number(a.ready)||Number(!!b.mon)-Number(!!a.mon));
 return `<div class="bond-intro"><span class="eyebrow">同行纪事 · 已留下 ${read} / 48 段回忆</span><h3>知道它擅长什么，<br>也慢慢知道它在想什么。</h3><p>每个潮灵家族都有三段故事。共同赢得对战会增加默契；故事随默契与星灯进度开放，进化和进入驿站都会保留。选择会留下不同的回应与纪念物。</p><div class="bond-milestones">${BOND_REQUIREMENTS.map((r,i)=>`<span><b>0${i+1}</b> 默契 ${r.bond}${r.badges?' · '+r.badges+' 枚灯印':' · 初识'}</span>`).join('')}</div></div><div class="tab-row bond-filters" role="group" aria-label="筛选同行故事">${[['owned','认识的伙伴'],['ready','可阅读 · '+ready],['all','全部家族']].map(([key,label])=>`<button data-bond-filter="${key}" class="${key===filter?'active':''}" aria-pressed="${key===filter}">${label}</button>`).join('')}</div><div class="bond-grid">${shown.map(s=>{const story=BOND_CHRONICLES[s.family],species=SPECIES[s.mon?.species||s.family],r=s.requirement;return `<article class="bond-card ${!s.mon?'unmet':''}" style="--bond-color:${ELEMENTS[species.element].color}"><div class="bond-card-art">${portrait(species.id)}<span>${s.complete?'✧ 三段已收好':s.ready?'✦ 有新的故事':s.mon?'默契 '+s.bond:'等待相遇'}</span></div><div class="bond-card-copy"><small>${s.mon?species.name+'家族':'未认识的潮灵'}</small><h3>${s.mon?story.title:'海的另一边，也有愿意同行的伙伴'}</h3><div class="bond-dots" aria-label="已读 ${s.step} 段">${[0,1,2].map(i=>`<i class="${i<s.step?'read':i===s.step&&s.ready?'ready':''}"></i>`).join('')}</div><p>${s.complete?'这些回忆可以随时重读。':!s.mon?'在群岛探索，与这位伙伴缔约。':s.ready?'新的片段，正等着你们一起留下。':`下一段需要默契 ${r.bond}${r.badges?'、'+r.badges+' 枚灯印':''}。`}</p>${s.mon?`<button class="text-button" data-bond-family="${s.family}">${s.ready?'看看新的故事':s.step?'查看已有回忆':'查看同行进度'} →</button>`:''}</div></article>`;}).join('')||'<p class="section-note">暂时没有新的片段。一起探索和对战，路上还会发生许多事。</p>'}</div>`;
}

export function bondFamilyMarkup(game,family){
 const s=bondStatus(game,family),story=BOND_CHRONICLES[family],species=SPECIES[s.mon?.species||family];
 return `<div class="bond-family-heading" style="--bond-color:${ELEMENTS[species.element].color}">${portrait(species.id,136)}<div><span class="eyebrow">${species.name}家族 · 默契 ${s.bond} / 100</span><h3>${story.title}</h3><p>与任一同家族伙伴积累的最高默契用于开放故事。每个家族的每段纪念物只领取一次。</p></div></div><div class="bond-chapters">${story.chapters.map((c,i)=>{const done=i<s.step,ready=i===s.step&&s.ready,r=BOND_REQUIREMENTS[i];return `<article class="${done?'read':ready?'ready':'locked'}"><span class="bond-chapter-number">${done?'✓':'0'+(i+1)}</span><div><small>${done?'已经留下的回忆':ready?'可以一起读了':'还需要一段旅途'}</small><h3>${done||ready?c.title:'尚未发生的故事'}</h3><p>${done?escape(c.choices[s.choices[i]].memory):`默契 ${r.bond}${r.badges?' · '+r.badges+' 枚灯印':''}`}</p>${done||ready?`<button class="text-button" data-bond-chapter="${i}">${done?'重读回忆':'和伙伴坐一会儿'} →</button>`:''}</div></article>`;}).join('')}</div><p class="section-note">每场胜利都会让同行队伍的默契增加 1。故事不要求连续游玩，也不会因为暂时离开而消失。</p><div class="card-actions"><button id="bond-index-back" class="secondary">全部同行故事</button><button id="bond-party-back" class="text-button">返回队伍</button></div>`;
}

export function bondReaderMarkup(game,family,index){
 const c=bondChapter(game,family,index),s=bondStatus(game,family),story=BOND_CHRONICLES[family],species=SPECIES[s.mon?.species||family],done=c.selected!==undefined;
 return `<div class="bond-reader-hero" style="--bond-color:${ELEMENTS[species.element].color}">${portrait(species.id,128)}<span>同行纪事 · ${story.title} · 0${index+1} / 03</span></div><div class="bond-prose">${c.lines.map(([who,line])=>`<p class="${who==='旁白'?'narrator':''}">${who==='旁白'?'':`<b>${who}</b>`}${escape(line)}</p>`).join('')}</div>${done?`<div class="bond-response"><small>你当时选择 · ${escape(c.choices[c.selected].label)}</small>${c.choices[c.selected].reply.map(([who,line])=>`<p><b>${who}</b>${escape(line)}</p>`).join('')}<p class="bond-kept-memory">✧ ${escape(c.choices[c.selected].memory)}</p></div><div class="bond-rewards"><small>这段回忆的纪念物 · 已收好</small>${rewardMarkup(bondReward(family,index,c.selected))}</div><button class="secondary" id="bond-reader-back">回到同行纪事</button>`:`<p class="bond-choice-prompt">你愿意怎样回应这位伙伴？</p><div class="bond-choices">${c.choices.map((choice,i)=>`<button data-bond-choice="${i}"><span>0${i+1}</span><strong>${escape(choice.label)}</strong>${index===2?`<small>留下 ${ITEMS[story.gifts[i]].name}<br>${ITEMS[story.gifts[i]].desc}</small>`:'<small>留下这一次回应 →</small>'}</button>`).join('')}</div>${index<2?`<div class="bond-rewards"><small>读完后收到的旅行补给</small>${rewardMarkup(bondReward(family,index,0))}</div>`:''}<p class="section-note">回应后会保存这段回忆。也可以先离开，想好以后再回来。</p>`}`;
}
